<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {activityInputTime,activityInstant} from './campaign-time.mjs'
import {ElButton,ElInput,ElSelect,ElOption,ElDialog,ElInputNumber,ElCheckbox,ElCheckboxGroup,ElDatePicker} from 'element-plus'
import {type Account} from '../../api'
import {confirmAction} from '../../shared/confirm'
import AdminListPager from '../../shared/list/AdminListPager.vue'
import AdminStatusBadge from '../../shared/list/AdminStatusBadge.vue'
import {useCurrentPageSelection} from '../../shared/list/useCurrentPageSelection'
import {useShippingConfig} from './use-shipping-config'
import {blankTemplate,money,type Template,type Campaign,type Target} from './types'
import {templateIssue} from './rule-validation.mjs'
import FenInput from './FenInput.vue'
import RegionSelector from './RegionSelector.vue'
import ShippingTargets from './ShippingTargets.vue'
import ShippingTrial from './ShippingTrial.vue'
import StoreSelector from './StoreSelector.vue'
import OperationMessage from './operation-message.vue'
import './shipping.css'
const props=defineProps<{account:Account}>(),state=useShippingConfig(),{config,loading,busy,error,notice,needsRead}=state
const permitted=computed(()=>props.account.permissionCodes.includes('settlement.shipping.manage'))
const query=ref(''),applied=ref(''),status=ref(''),appliedStatus=ref(''),page=ref(1),size=ref(20)
const filtered=computed(()=>config.value?.templates.filter(t=>t.name.includes(applied.value)&&(appliedStatus.value===''||String(t.enabled)===appliedStatus.value))||[])
const rows=computed(()=>filtered.value.slice((page.value-1)*size.value,page.value*size.value)),selection=useCurrentPageSelection(()=>rows.value,t=>t.id)
const editor=ref<Template|null>(null),campaign=ref<Campaign|null>(null),weightOpen=ref(false),weights=ref<Record<string,number|null>>({}),weightTargets=ref<Target[]>([])
const trialOpen=ref(false)
const unit=computed(()=>editor.value?.mode==='WEIGHT'?'克':'件')
const issue=computed(()=>editor.value?templateIssue(editor.value):'')
function search(){applied.value=query.value.trim();appliedStatus.value=status.value;page.value=1}
function edit(row?:Template){editor.value=row?JSON.parse(JSON.stringify(row)):blankTemplate();error.value=''}
async function saveTemplate(){if(!editor.value||issue.value){error.value=issue.value;return}const {id,...fields}=editor.value,body={...fields,regions:fields.regions.map(({code,name,level})=>({code,name,level})),blockedRegions:fields.blockedRegions.map(({code,name,level})=>({code,name,level}))};if(await state.write(id?`templates/${encodeURIComponent(id)}`:'templates',id?'PUT':'POST',body))editor.value=null}
async function remove(t:Template){if(!await confirmAction(`删除运费模板“${t.name}”？已生成的订单保持原运费快照。`,{confirmButtonText:'删除模板'}))return;await state.write(`templates/${encodeURIComponent(t.id)}`,'DELETE',{})}
async function bulk(enabled:boolean){if(!selection.selectedIds.value.length||!await confirmAction(`确认${enabled?'启用':'停用'}所选 ${selection.selectedIds.value.length} 个模板？`))return;await state.write('bulk','POST',{resource:'templates',ids:selection.selectedIds.value,enabled});selection.clear()}
function openCampaign(){const now=new Date(),end=new Date(now.getTime()+86400000);campaign.value=config.value?{enabled:false,name:'平台包邮活动',startsAt:now.toISOString(),endsAt:end.toISOString(),minimumFen:19900,storeIds:[],deliveryModes:['EXPRESS','DELIVERY'],...JSON.parse(JSON.stringify(config.value.campaign))}:null;if(campaign.value){campaign.value={...campaign.value,startsAt:activityInputTime(campaign.value.startsAt),endsAt:activityInputTime(campaign.value.endsAt)}}}
async function saveCampaign(){if(!campaign.value)return;const c=campaign.value;if(!c.name.trim()||!c.startsAt||!c.endsAt||new Date(c.startsAt)>=new Date(c.endsAt)||!c.deliveryModes.length){error.value='请填写活动名称、有效起止时间和配送方式。';return}if(await state.write('config','PATCH',{campaign:{...c,startsAt:c.startsAt?activityInstant(c.startsAt):null,endsAt:c.endsAt?activityInstant(c.endsAt):null}}))campaign.value=null}
function receiveTargets(targets:Target[]){weightTargets.value=[...weightTargets.value.filter(p=>!targets.some(t=>t.productId===p.productId)),...targets]}
function openWeights(){weights.value={};weightTargets.value=[];weightOpen.value=true}
async function saveWeights(){const items=Object.entries(weights.value).filter(([,value])=>value!==null).map(([skuId,weightGrams])=>({skuId,weightGrams,expectedUnitVersionId:weightTargets.value.flatMap(p=>p.skus).find(s=>s.skuId===skuId)?.unitVersionId}));if(!items.length){error.value='请至少填写一个规格的克重。';return}if(await state.write('weights','PUT',{items}))weightOpen.value=false}
watch(state.recoveryCounter,()=>{editor.value=null;campaign.value=null;weightOpen.value=false;selection.clear()})
watch(()=>[props.account.accountId,props.account.permissionCodes.join(',')],()=>{state.reset();editor.value=null;campaign.value=null;weightOpen.value=false;trialOpen.value=false;selection.clear();if(permitted.value)state.load()},{immediate:true})
</script>
<template><section class="page-content shipping-page"><header class="page-heading"><div><h1>快递与包邮</h1><p>运费以服务端报价为准。经营包邮由前置仓承担，平台活动包邮由平台承担。</p></div><ElButton type="primary" :disabled="!config||busy||needsRead" @click="edit()">新增运费模板</ElButton></header><p v-if="!permitted" role="alert">当前账号没有配送规则配置权限。</p><template v-else><p v-if="loading" role="status">正在读取配送规则…</p><p v-if="error" class="error" role="alert">{{error}} <ElButton :disabled="busy" @click="state.load">重新读取</ElButton></p><p v-if="notice" class="notice" role="status">{{notice}}</p><template v-if="config&&!loading"><form class="panel admin-list-filters inline-fields" @submit.prevent="search"><label>模板名称<ElInput v-model="query" maxlength="100" aria-label="模板名称"/></label><label>模板状态<ElSelect v-model="status" aria-label="模板状态" style="width:150px"><ElOption label="全部状态" value=""/><ElOption label="已启用" value="true"/><ElOption label="已停用" value="false"/></ElSelect></label><ElButton native-type="submit" type="primary">查询</ElButton><ElButton @click="query='';status='';search()">重置</ElButton></form><div class="rule-toolbar"><div class="inline-fields"><span>已选 {{selection.selectedIds.value.length}} 项</span><ElButton :disabled="!selection.selectedIds.value.length||busy||needsRead" @click="bulk(true)">批量启用</ElButton><ElButton :disabled="!selection.selectedIds.value.length||busy||needsRead" @click="bulk(false)">批量停用</ElButton></div><div><ElButton :disabled="busy" @click="trialOpen=true">快递运费试算</ElButton><ElButton :disabled="busy||needsRead" @click="openWeights">规格重量配置</ElButton><ElButton :disabled="busy||needsRead" @click="openCampaign">平台包邮活动</ElButton></div></div><div class="panel table-wrap admin-list-table" tabindex="0" aria-label="运费模板列表"><table><thead><tr><th><input type="checkbox" aria-label="选择当前页全部模板" :checked="selection.allSelected.value" :indeterminate="selection.indeterminate.value" @change="selection.togglePage(($event.target as HTMLInputElement).checked)"></th><th>模板</th><th>计费</th><th>包邮门槛</th><th>配送地区</th><th>关联商品</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="t in rows" :key="t.id"><td><input type="checkbox" :aria-label="`选择 ${t.name}`" :checked="selection.selectedIds.value.includes(t.id)" @change="selection.toggle(t.id,($event.target as HTMLInputElement).checked)"></td><td>{{t.name}}</td><td>{{({FIXED:'按单',PIECE:'按件',WEIGHT:'按重量'})[t.mode]}} {{money(t.firstFeeFen)}}<small v-if="t.mode!=='FIXED'">首 {{t.firstUnits}}{{t.mode==='WEIGHT'?'克':'件'}}；续 {{t.extraUnits}}{{t.mode==='WEIGHT'?'克':'件'}} {{money(t.extraFeeFen)}}</small></td><td>{{money(t.freeThresholdFen)}}</td><td>{{t.regions.map(r=>r.name).join('、')||'全国'}}<small>禁配：{{t.blockedRegions.map(r=>r.name).join('、')||'无'}}</small></td><td>{{t.productIds.length?`${t.productIds.length} 个商品`:'默认模板'}}</td><td><AdminStatusBadge :status="t.enabled?'ACTIVE':'DISABLED'" :label="t.enabled?'已启用':'已停用'" :tone="t.enabled?'success':'neutral'"/></td><td><ElButton link type="primary" :disabled="busy||needsRead" @click="edit(t)">编辑</ElButton><ElButton link type="danger" :disabled="busy||needsRead" @click="remove(t)">删除</ElButton></td></tr><tr v-if="!rows.length"><td colspan="8">暂无符合条件的模板。请新增并启用模板后开放快递发货。</td></tr></tbody></table></div><AdminListPager :page="page" :page-size="size" :total="filtered.length" @change="(p,s)=>{page=p;size=s}"/><section class="panel" style="margin-top:20px"><h2>平台包邮活动</h2><p>{{config.campaign.enabled?config.campaign.name:'未启用平台活动包邮'}} · {{config.campaign.enabled?`活动门槛 ${money(config.campaign.minimumFen)}`:'经营包邮继续按模板门槛判断'}}</p><small>活动符合条件时平台承担运费；退出活动后按经营规则计费。已有订单保持成交时承担快照。</small></section></template></template>
<ElDialog :model-value="!!editor" :title="editor?.id?'编辑运费模板':'新增运费模板'" width="min(900px,94vw)" :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy" @update:model-value="v=>{if(!v&&!busy)editor=null}"><template v-if="editor"><OperationMessage :error="error" :needs-read="needsRead" :busy="busy" @reload="state.load"/><div class="rule-fields"><label>模板名称<ElInput v-model="editor.name" maxlength="100" :disabled="busy"/></label><label>计费方式<ElSelect v-model="editor.mode" :disabled="busy"><ElOption label="按单固定运费" value="FIXED"/><ElOption label="按件" value="PIECE"/><ElOption label="按重量（克）" value="WEIGHT"/></ElSelect></label><FenInput v-model="editor.firstFeeFen" :label="editor.mode==='FIXED'?'每单运费':'首段运费'" :disabled="busy"/><label v-if="editor.mode!=='FIXED'">首段数量（{{unit}}）<ElInputNumber v-model="editor.firstUnits"  :min="1" :max="1000000" :precision="0" :disabled="busy"/></label><FenInput v-if="editor.mode!=='FIXED'" v-model="editor.extraFeeFen" label="续段运费" :disabled="busy"/><label v-if="editor.mode!=='FIXED'">续段数量（{{unit}}）<ElInputNumber v-model="editor.extraUnits"  :min="1" :max="1000000" :precision="0" :disabled="busy"/></label><FenInput v-model="editor.freeThresholdFen" label="经营包邮门槛" nullable :disabled="busy"/><ElCheckbox v-model="editor.enabled" :disabled="busy">启用模板</ElCheckbox></div><RegionSelector v-model="editor.regions" label="可配送地区" :disabled="busy"/><RegionSelector v-model="editor.blockedRegions" label="禁配地区" :disabled="busy"/><h3>关联商品</h3><ShippingTargets v-model="editor.productIds" :disabled="busy"/><p v-if="issue" role="status">{{issue}}</p></template><template #footer><ElButton :disabled="busy" @click="editor=null">取消</ElButton><ElButton type="primary" :loading="busy" :disabled="!!issue||needsRead" @click="saveTemplate">保存模板</ElButton></template></ElDialog>
<ElDialog :model-value="!!campaign" title="平台包邮活动" width="min(680px,94vw)" :close-on-click-modal="false" :show-close="!busy" @update:model-value="v=>{if(!v&&!busy)campaign=null}"><template v-if="campaign"><OperationMessage :error="error" :needs-read="needsRead" :busy="busy" @reload="state.load"/><p>活动包邮的运费由平台承担。</p><div class="rule-fields"><label>活动名称<ElInput v-model="campaign.name" maxlength="100" :disabled="busy"/></label><FenInput v-model="campaign.minimumFen" label="活动商品金额门槛" :disabled="busy"/><label>开始时间（北京时间）<ElDatePicker v-model="campaign.startsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" :disabled="busy"/></label><label>结束时间（北京时间）<ElDatePicker v-model="campaign.endsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" :disabled="busy"/></label><ElCheckboxGroup v-model="campaign.deliveryModes"><ElCheckbox label="快递发货" value="EXPRESS" :disabled="busy"/><ElCheckbox label="前置仓配送" value="DELIVERY" :disabled="busy"/></ElCheckboxGroup><StoreSelector v-model="campaign.storeIds" :disabled="busy"/><ElCheckbox v-model="campaign.enabled" :disabled="busy">启用平台活动</ElCheckbox></div><p>适用前置仓：{{campaign.storeIds.length?`${campaign.storeIds.length} 家`:'全部前置仓'}}</p></template><template #footer><ElButton :disabled="busy" @click="campaign=null">取消</ElButton><ElButton type="primary" :loading="busy" :disabled="needsRead" @click="saveCampaign">保存活动</ElButton></template></ElDialog>
<ElDialog v-model="weightOpen" :close-on-press-escape="!busy" title="规格重量配置" width="min(820px,94vw)" :close-on-click-modal="false" :show-close="!busy"><OperationMessage :error="error" :needs-read="needsRead" :busy="busy" @reload="state.load"/><ShippingTargets v-if="weightOpen" :model-value="[]" weights v-model:weight-values="weights" :disabled="busy" @targets="receiveTargets"/><template #footer><ElButton :disabled="busy" @click="weightOpen=false">取消</ElButton><ElButton type="primary" :loading="busy" :disabled="needsRead" @click="saveWeights">保存规格重量</ElButton></template></ElDialog><ElDialog v-model="trialOpen" title="快递运费试算" width="min(850px,94vw)" :close-on-click-modal="false"><ShippingTrial v-if="trialOpen" :store-id="null" mode="EXPRESS"/><template #footer><ElButton @click="trialOpen=false">关闭</ElButton></template></ElDialog></section></template>
